solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <optional>
#include <vector>

std::vector<std::uint8_t> frame(const std::vector<std::uint8_t>& payload)
{
    const auto n{ static_cast<std::uint32_t>(payload.size()) };
    std::vector<std::uint8_t> out{ static_cast<std::uint8_t>(n), static_cast<std::uint8_t>(n >> 8), static_cast<std::uint8_t>(n >> 16), static_cast<std::uint8_t>(n >> 24) };
    out.insert(out.end(), payload.begin(), payload.end());
    return out;
}

class Deframer
{
public:
    explicit Deframer(std::uint32_t maxMessage) : maxMessage{ maxMessage } {}

    void feed(const std::vector<std::uint8_t>& bytes)
    {
        if (!bad) buffer.insert(buffer.end(), bytes.begin(), bytes.end());
    }

    std::optional<std::vector<std::uint8_t>> next()
    {
        if (bad || buffer.size() < 4) return std::nullopt;
        const std::uint32_t length{ buffer[0] | (buffer[1] << 8) | (buffer[2] << 16) | (static_cast<std::uint32_t>(buffer[3]) << 24) };
        if (length > maxMessage) { bad = true; buffer.clear(); return std::nullopt; }
        if (buffer.size() - 4 < length) return std::nullopt;
        std::vector<std::uint8_t> payload(buffer.begin() + 4, buffer.begin() + 4 + length);
        buffer.erase(buffer.begin(), buffer.begin() + 4 + length);
        return payload;
    }

    bool failed() const { return bad; }

private:
    std::uint32_t maxMessage;
    std::vector<std::uint8_t> buffer;
    bool bad{ false };
};

struct MessageRead { std::vector<std::uint8_t> bytes; bool moreData; };

std::vector<MessageRead> readInMessageMode(const std::vector<std::uint8_t>& message, std::size_t bufferSize)
{
    std::vector<MessageRead> reads;
    std::size_t at{ 0 };
    do
    {
        const std::size_t n{ std::min(bufferSize, message.size() - at) };
        reads.push_back({ { message.begin() + static_cast<std::ptrdiff_t>(at), message.begin() + static_cast<std::ptrdiff_t>(at + n) }, at + n < message.size() });
        at += n;
    } while (at < message.size());
    return reads;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
static Bytes text(const char* s) { return Bytes(s, s + std::char_traits<char>::length(s)); }

TEST("framing") {
    CHECK(frame(text("hello")) == (Bytes{ 5, 0, 0, 0, 'h', 'e', 'l', 'l', 'o' }));
    CHECK(frame({}) == (Bytes{ 0, 0, 0, 0 }));
    CHECK_EQ(frame(Bytes(300, 7))[1], 1);
}
TEST("deframing a stream in pieces") {
    Bytes stream{ frame(text("hello")) };
    const Bytes second{ frame(text("world!")) }, empty{ frame({}) };
    stream.insert(stream.end(), second.begin(), second.end());
    stream.insert(stream.end(), empty.begin(), empty.end());
    Deframer d{ 1024 };
    std::vector<Bytes> got;
    for (std::size_t i{ 0 }; i < stream.size(); i += 3)
    {
        d.feed(Bytes(stream.begin() + static_cast<std::ptrdiff_t>(i), stream.begin() + static_cast<std::ptrdiff_t>(std::min(i + 3, stream.size()))));
        while (auto m{ d.next() }) got.push_back(*m);
    }
    CHECK_EQ(got.size(), 3u);
    if (got.size() == 3) { CHECK(got[0] == text("hello")); CHECK(got[1] == text("world!")); CHECK(got[2].empty()); }
    CHECK(!d.failed());
}
TEST("absurd lengths fail the stream") {
    Deframer d{ 16 };
    d.feed({ 0xFF, 0xFF, 0xFF, 0xFF, 1, 2, 3 });
    CHECK(!d.next().has_value());
    CHECK(d.failed());
    d.feed(frame(text("ok")));
    CHECK(!d.next().has_value());
    Deframer edge{ 2 };
    edge.feed(frame(text("ok")));
    CHECK(edge.next().has_value());
}
TEST("message mode reads") {
    const auto reads{ readInMessageMode(text("abcdefghij"), 4) };
    CHECK_EQ(reads.size(), 3u);
    if (reads.size() == 3) { CHECK(reads[0].moreData); CHECK(reads[1].moreData); CHECK(!reads[2].moreData); CHECK(reads[2].bytes == text("ij")); }
    const auto exact{ readInMessageMode(text("abcd"), 4) };
    CHECK_EQ(exact.size(), 1u);
    if (!exact.empty()) CHECK(!exact[0].moreData);
    const auto none{ readInMessageMode({}, 4) };
    CHECK_EQ(none.size(), 1u);
    if (!none.empty()) { CHECK(none[0].bytes.empty()); CHECK(!none[0].moreData); }
}

